CREATE OR REPLACE FUNCTION public.apply_schedule_dates(_project_id uuid, _updates jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ DECLARE requested integer; changed integer; BEGIN IF jsonb_typeof(_updates) <> 'array' THEN RAISE EXCEPTION 'Schedule updates must be an array'; END IF; requested := jsonb_array_length(_updates); IF requested <> (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(_updates) x) THEN RAISE EXCEPTION 'Duplicate activity identities in approval'; END IF; UPDATE public.tasks t SET start_date=(x.start_date)::timestamptz, updated_at=now() FROM jsonb_to_recordset(_updates) AS x(id uuid,start_date text) WHERE t.id=x.id AND t.project_id=_project_id; GET DIAGNOSTICS changed = ROW_COUNT; IF changed <> requested THEN RAISE EXCEPTION 'Schedule approval failed: an activity is missing or not editable'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.apply_schedule_dates(uuid,jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.apply_schedule_dates(uuid,jsonb) TO authenticated, service_role;